<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api,formatEventTime} from '../api.js';
import {subscribe} from '../realtime.js';
import Avatar from '../components/Avatar.vue';

const route=useRoute(),router=useRouter(),id=String(route.params.id),club=ref(null),runs=ref([]),members=ref([]),messages=ref([]),tab=ref('runs'),draft=ref(''),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('');
let cursor=0,live=false,stop,timer,closed=false,loadingMessages=false;
async function load(){loading.value=true;error.value='';try{const result=await api('/api/clubs/'+encodeURIComponent(id));club.value=result.club;runs.value=result.events||[];members.value=result.members||[];if(result.canChat)connectChat();else{stop?.();stop=null;}}catch(e){error.value=e.message;if([403,404].includes(e.status))club.value=null;}finally{loading.value=false;}}
async function join(){if(busy.value)return;busy.value=true;error.value='';try{await api(`/api/clubs/${encodeURIComponent(id)}/join`,{method:'POST',body:{}});notice.value='You joined the run club.';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function leave(){if(busy.value||!confirm('Leave this run club? You can join again later.'))return;busy.value=true;error.value='';try{await api(`/api/clubs/${encodeURIComponent(id)}/membership`,{method:'DELETE'});notice.value='You left the run club.';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function archive(){if(busy.value||!confirm('Archive this run club? Its runs and chat history will remain stored, but members will lose access.'))return;busy.value=true;error.value='';try{await api(`/api/clubs/${encodeURIComponent(id)}/archive`,{method:'DELETE'});await router.push('/app/run-clubs');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function rsvp(run){if(busy.value)return;busy.value=true;error.value='';try{const result=await api(`/api/events/${run.id}/rsvp`,{method:'POST',body:{going:!run.mine}});run.mine=result.going;run.going=result.count;await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function loadMessages(){if(!club.value?.joined||loadingMessages||closed)return;loadingMessages=true;try{const result=await api(`/api/clubs/${encodeURIComponent(id)}/messages?after=${cursor}`);if(closed)return;const known=new Map(messages.value.map(message=>[String(message.id),message]));for(const message of result.messages||[])known.set(String(message.id),message);messages.value=[...known.values()].sort((a,b)=>Number(a.id)-Number(b.id));cursor=Number(result.cursor||cursor);}catch(e){if([403,404].includes(e.status)){error.value=e.message;stop?.();stop=null;}}finally{loadingMessages=false;}}
function connectChat(){if(stop)return;stop=subscribe(`club:${id}`,loadMessages,state=>live=state);timer=setInterval(()=>{if(!live&&document.visibilityState==='visible')loadMessages();},15000);}
async function send(){if(!draft.value.trim()||busy.value)return;busy.value=true;error.value='';try{await api(`/api/clubs/${encodeURIComponent(id)}/messages`,{method:'POST',body:{body:draft.value.trim()}});draft.value='';await loadMessages();}catch(e){error.value=e.message;}finally{busy.value=false;}}
watch(tab,value=>{if(value==='chat')loadMessages();});
onMounted(load);
onBeforeUnmount(()=>{closed=true;stop?.();clearInterval(timer);});
</script>
<template>
 <main class="run-club">
  <p v-if="loading" role="status" class="mute">Loading run club…</p><template v-else-if="club">
   <header class="club-head"><RouterLink to="/app/run-clubs">Run clubs</RouterLink><div class="row between"><div><span class="tag">{{club.city}}</span><h1>{{club.name}}</h1><p class="mute">Organized by {{club.organizer_name}} · {{club.members}} members</p></div><div class="row club-controls"><button v-if="!club.joined" class="btn" :disabled="busy" @click="join">Join this club</button><button v-else-if="!club.isOrganizer" class="btn ghost sm" :disabled="busy" @click="leave">Leave club</button><template v-else><span class="tag">Organizer</span><button class="btn ghost sm" :disabled="busy" @click="archive">Archive club</button></template></div></div><p v-if="club.description" class="description">{{club.description}}</p></header>
   <p v-if="error" class="err" role="alert">{{error}}</p><p v-if="notice" class="ok" role="status">{{notice}}</p>
   <nav v-if="club.joined" class="chips tabs" aria-label="Run club sections"><button class="chip" :aria-pressed="tab==='runs'" @click="tab='runs'">Upcoming runs</button><button class="chip" :aria-pressed="tab==='chat'" @click="tab='chat'">Club chat</button><button class="chip" :aria-pressed="tab==='members'" @click="tab='members'">Members</button></nav>
   <section v-if="tab==='runs'" class="runs"><div class="row between"><h2>Upcoming runs</h2><RouterLink v-if="club.isOrganizer" class="btn ghost sm" :to="`/app/events?clubId=${club.id}`">Add a run</RouterLink></div><p v-if="!runs.length" class="mute">No runs listed yet. The organizer can add the first one from Sessions.</p><article v-for="run in runs" :key="run.id" class="card run"><div><span class="tag hot">{{run.kind}}</span><span v-if="run.weekly" class="tag">Weekly</span><h3>{{run.title}}</h3><p class="mute small">{{formatEventTime(run.startsAt,run.timezone).day}} · {{formatEventTime(run.startsAt,run.timezone).time}} · {{run.location}}</p><div class="row people"><Avatar v-for="person in run.attendees" :key="person.id" :person="person" :size="28"/><span class="mute small">{{run.going===0?'Be the first to join':`${run.going} going`}}</span></div></div><div class="run-actions"><button class="btn sm" :class="{ghost:run.mine}" :disabled="busy||(!run.mine&&run.capacity&&run.going>=run.capacity)" @click="rsvp(run)">{{run.mine?'Leave':run.capacity&&run.going>=run.capacity?'Full':'Join run'}}</button><RouterLink v-if="run.mine||run.isHost" class="btn ghost sm" :to="`/app/events/${run.id}/chat`">Run chat</RouterLink></div></article></section>
   <section v-else-if="tab==='chat'&&club.joined" class="club-chat"><h2>Club chat</h2><div class="messages" aria-live="polite"><p v-if="!messages.length" class="mute">Start the conversation.</p><article v-for="message in messages" :key="message.id" class="message" :class="{mine:message.mine}"><b v-if="!message.mine">{{message.name}}</b><p>{{message.body}}</p><time>{{new Date(message.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}}</time></article></div><form class="row" @submit.prevent="send"><input v-model="draft" class="grow" maxlength="2000" placeholder="Message club members" aria-label="Message club members" :disabled="busy"><button class="btn sm" :disabled="busy||!draft.trim()">Send</button></form></section>
   <section v-else-if="tab==='members'&&club.joined"><h2>Club members</h2><div class="members"><div v-for="member in members" :key="member.id" class="member"><Avatar :person="member" :size="40"/><span>{{member.name}}</span><span v-if="member.id===club.organizer_id" class="tag">Organizer</span></div></div></section>
  </template><p v-else-if="!loading" class="mute">This run club is unavailable.</p></main>
</template>
<style scoped>
.club-head{border-bottom:1px solid var(--line);padding-bottom:22px}.club-head h1{font-size:30px;margin:8px 0}.club-head .between{justify-content:space-between;align-items:flex-start;gap:16px}.club-head p{margin:8px 0}.club-controls{align-items:center}.description{white-space:pre-wrap;line-height:1.6}.tabs{margin:18px 0}.runs>h2,.club-chat h2{font-size:22px}.runs>.between{justify-content:space-between}.run{display:flex;justify-content:space-between;gap:18px;margin:12px 0}.run h3{font-size:19px;margin:10px 0 5px}.run p{margin:6px 0}.people{align-items:center;margin-top:10px}.run-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.club-chat{display:flex;flex-direction:column;min-height:430px}.messages{overflow:auto;flex:1;max-height:55vh;margin:12px 0}.message{width:fit-content;max-width:85%;border:1px solid var(--line);background:var(--card);padding:10px 14px;margin:8px 0;overflow-wrap:anywhere}.message.mine{margin-left:auto;background:var(--soft)}.message p{white-space:pre-wrap;margin:3px 0}.message b,.message time{font-size:12px}.message time{color:var(--mute)}.members{display:grid;gap:10px}.member{display:flex;align-items:center;gap:10px}.member .tag{margin-left:auto}
</style>
